Here is the root cause:
The bug arises because `vmalloc` does not allocate a `vm_struct` for memory areas created with `vm_map_ram()`, leading to usercopy operations being denied for these areas. This affects functionalities like XFS that rely on `vm_map_ram()` for directory management, as the system cannot properly identify and handle these memory regions during usercopy operations.

Here is the patch:

 static inline void check_heap_object(const void *ptr, unsigned long n,
 				     bool to_user)
 {
 	struct folio *folio;

 	if (is_kmap_addr(ptr)) {
 		unsigned long page_end = (unsigned long)ptr | (PAGE_SIZE - 1);

 		if ((unsigned long)ptr + n - 1 > page_end)
 			usercopy_abort("kmap", NULL, to_user,
 					offset_in_page(ptr), n);
 		return;
 	}

 	if (is_vmalloc_addr(ptr)) {
-		struct vm_struct *area = find_vm_area(ptr);
+		struct vmap_area *area = find_vmap_area((unsigned long)ptr);
 		unsigned long offset;

-		if (!area) {
+		if (!area)
 			usercopy_abort("vmalloc", "no area", to_user, 0, n);
-			return;
-		}

-		offset = ptr - area->addr;
-		if (offset + n > get_vm_area_size(area))
+		offset = (unsigned long)ptr - area->va_start;
+		if ((unsigned long)ptr + n > area->va_end)
 			usercopy_abort("vmalloc", NULL, to_user, offset, n);
 		return;
 	}

 	if (!virt_addr_valid(ptr))
 		return;

 	folio = virt_to_folio(ptr);

 	if (folio_test_slab(folio)) {
 		/* Check slab allocator for flags and size. */
 		__check_heap_object(ptr, n, folio_slab(folio), to_user);
 	} else if (folio_test_large(folio)) {
 		unsigned long offset = ptr - folio_address(folio);
 		if (offset + n > folio_size(folio))
 			usercopy_abort("page alloc", NULL, to_user, offset, n);
 	}
 }



